            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Salut petit frère ! Salut en bâtardise ! Car toi aussi tu es un bâtard ! Pour t'engendrer, le clergé a couché avec Misère ; quelle maussade volupté !", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je me moque du Diable ! Il reçoit les âmes, mais ce n'est pas lui qui les damne. Je ne daigne avoir affaire qu'à Dieu, les monstres et les saints ne relèvent que de lui.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "De quoi te mêles-tu ? (Un temps.) Le mal, ça doit faire mal à tout le monde. Et d'abord à celui qui le fait.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Alors réjouis-toi, je la prendrai. Mais pourquoi ? Parce que c'est mal. Et pourquoi faire le Mal ? Parce que le Bien est déjà fait. Qui l'a fait ? Dieu le Père. Moi, j'invente.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "L'égal de tous les hommes ou le valet de tous les princes : choisis.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Le monde est iniquité ; si tu l'acceptes tu es complice, si tu le changes, tu es bourreau.", Author = "Jean-Paul Sartre" },
