            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je ne serai pas modeste. Humble tant qu'on voudra, mais pas modeste. La modestie est la vertu des tièdes.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je sais que le Bien est plus pénible que le Mal. Le Mal ce n'était que moi, le Bien c'est tout.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Encore le jeu du pardon ? (Un temps.) C'est un jeu qui m'ennuie : je ne suis pas dans le coup. Je n'ai qualité ni pour condamner ni pour absoudre : c'est l'affaire de Dieu.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Je ne veux pas que tu te réjouisses d'avoir mis des hommes à quatre pattes.", Author = "Jean-Paul Sartre" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Paul_Sartre", Text = "Vous aussi, le Diable vous guette. Qui donc aura pitié de vous si vous n'avez pas pitié d'elle ? Qui donc aimera les pauvres si les pauvres ne s'aiment pas entre eux ?", Author = "Jean-Paul Sartre" },
